-- Seed company tags for well-known LeetCode problems asked at FAANG companies.
-- This covers the most frequently asked problems at each company.
-- Source: public datasets of company-tagged LeetCode problems.

-- Google
UPDATE public.coding_problems SET company_tags = array_append(company_tags, 'Google')
WHERE leetcode_id IN ('1','2','3','4','5','11','15','17','20','22','23','33','34','39','42','46','48','49','53','56','62','70','72','76','78','79','84','91','98','102','121','124','127','128','130','133','139','146','152','155','188','198','200','206','207','208','210','212','215','218','221','226','230','236','238','239','240','253','269','271','279','283','285','295','297','300','301','303','322','329','332','340','347','380','394','399','410','417','438','472','486','489','493','518','525','528','560','588','621','642','670','680','684','694','695','715','727','729','731','733','735','739','743','763','767','785','787','815','818','833','843','844','846','849','855','857','862','894','929','939','946','951','973','975','981','986','987','1048','1055','1110','1146','1197','1249','1293','1373','1438','1466','1477','1514','1548','1610','1631','1696','1762','1834','1857');

